@import url('https://discordstyles.github.io/FrostedGlass/FrostedGlass.css');
@import url('https://discordstyles.github.io/Addons/windows-titlebar.css');
@import url('https://discordstyles.github.io/Addons/windows-titlebar.css');

:root {
  --background-image: url('data:image/jpeg;base64,');
  --background-image-blur: 0px;
  --background-image-size: cover;
  --background-image-position: center;
  --popout-image: var(--background-image);
  --popout-image-blur: 8px;
  --popout-image-size: contain;
  --popout-image-position: center;
  --overlay-image: var(--background-image);
  --overlay-image-blur: 11px;
  --overlay-image-size: cover;
  --overlay-image-position: center;
  --home-button-image: url('https://gibbu.github.io/BetterDiscord-Themes/FrostedGlass/assets/discord.svg');
  --home-button-size: cover;
  --home-button-position: center;
  --serverlist-brightness: 0;
  --left-brightness: 0;
  --middle-brightness: 0.5;
  --right-brightness: 0.22;
  --overlay-brightness: 0;
  --gradient-primary: 57,76,166;
  --gradient-secondary: 45,185,203;
  --link-colour: #FFEB3B;
  --scrollbar-colour: rgb(0,210,255,0.5);
  --gradient-direction: 360deg;
  --tint-colour: 255,51,159;
  --tint-brightness: 0;
  --font: Cormorant Garamond;
  --window-padding: 10px;
  --window-roundness: 10px;
  --update-notice-1: none;
}

